import { NextRequest, NextResponse } from 'next/server';
import { createClient } from '@/lib/milvus-client';
import { cookies } from 'next/headers';

export async function POST(request: NextRequest) {
  try {
    const body = await request.json();
    const { address, token } = body;

    if (!address || !token) {
      return NextResponse.json(
        { error: 'Address and token are required' },
        { status: 400 }
      );
    }

    const { clientId } = createClient(address, token);

    const response = NextResponse.json({ clientId, success: true });

    // Set cookies in response headers directly
    // Store clientId, address, and token so we can recreate client if cache is lost
    response.cookies.set('clientId', clientId, {
      httpOnly: true,
      secure: process.env.NODE_ENV === 'production',
      sameSite: 'lax',
      maxAge: 60 * 60 * 24 * 7, // 7 days
      path: '/',
    });

    // Store address and token (encoded) for client recreation
    response.cookies.set('milvus_address', Buffer.from(address).toString('base64'), {
      httpOnly: true,
      secure: process.env.NODE_ENV === 'production',
      sameSite: 'lax',
      maxAge: 60 * 60 * 24 * 7, // 7 days
      path: '/',
    });

    response.cookies.set('milvus_token', Buffer.from(token).toString('base64'), {
      httpOnly: true,
      secure: process.env.NODE_ENV === 'production',
      sameSite: 'lax',
      maxAge: 60 * 60 * 24 * 7, // 7 days
      path: '/',
    });

    return response;
  } catch (error: any) {
    console.error('Auth connect error:', error);
    return NextResponse.json(
      { error: error.message || 'Failed to connect' },
      { status: 500 }
    );
  }
}

import { NextResponse } from 'next/server';
import { cookies } from 'next/headers';

export async function GET(request: Request) {
  const response = NextResponse.redirect(new URL('/login', request.url));

  // Clear all auth cookies
  response.cookies.delete('clientId');
  response.cookies.delete('milvus_address');
  response.cookies.delete('milvus_token');

  return response;
}

import { ErrorCode, MilvusClient } from '../../milvus';

describe('utils/Compaction', () => {
  it('should forward advanced compaction params to ManualCompaction', async () => {
    const client = new MilvusClient({
      address: 'localhost:19530',
      __SKIP_CONNECT__: true,
    });

    let describeParams: any;
    let compactionParams: any;
    (client as any).channelPool = {
      acquire: jest.fn().mockResolvedValue({
        DescribeCollection: (params: any, _options: any, cb: any) => {
          describeParams = params;
          cb(null, {
            status: { error_code: ErrorCode.SUCCESS, reason: '' },
            collectionID: '100',
            schema: { fields: [], functions: [] },
            consistency_level: 'Bounded',
            properties: [],
            aliases: [],
            virtual_channel_names: [],
            physical_channel_names: [],
            start_positions: [],
          });
        },
        ManualCompaction: (params: any, _options: any, cb: any) => {
          compactionParams = params;
          cb(null, {
            status: { error_code: ErrorCode.SUCCESS, reason: '' },
            compactionID: '1',
            compactionPlanCount: 1,
          });
        },
      }),
      release: jest.fn(),
    };

    const res = await client.compact({
      collection_name: 'test_collection',
      db_name: 'test_db',
      timetravel: '123',
      majorCompaction: true,
      partition_id: '456',
      channel: 'by-dev-rootcoord-dml_0',
      segment_ids: [111, 222],
      l0Compaction: true,
      target_size: '536870912',
      timeout: 1000,
    });

    expect(res.status.error_code).toEqual(ErrorCode.SUCCESS);
    expect(describeParams).toEqual({
      collection_name: 'test_collection',
      db_name: 'test_db',
      timeout: 1000,
    });
    expect(compactionParams).toEqual({
      collection_name: 'test_collection',
      db_name: 'test_db',
      collectionID: '100',
      timetravel: '123',
      majorCompaction: true,
      partition_id: '456',
      channel: 'by-dev-rootcoord-dml_0',
      segment_ids: [111, 222],
      l0Compaction: true,
      target_size: '536870912',
    });
    expect(compactionParams).not.toHaveProperty('timeout');
  });
});

import { MilvusClient, DataType, ErrorCode, ERROR_REASONS } from '../../milvus';
import {
  IP,
  generateInsertData,
  genCollectionParams,
  GENERATE_NAME,
} from '../tools';

const milvusClient = new MilvusClient({
  address: IP,
  logLevel: 'info',
});

const COLLECTION_NAME = GENERATE_NAME();
const dbParam = {
  db_name: 'Compaction',
};

const createCollectionParams = genCollectionParams({
  collectionName: COLLECTION_NAME,
  dim: [4],
  vectorType: [DataType.FloatVector],
  autoID: false,
});

describe(`Compaction API`, () => {
  beforeAll(async () => {
    await milvusClient.createDatabase(dbParam);
    await milvusClient.use(dbParam);
    await milvusClient.createCollection(createCollectionParams);

    await milvusClient.insert({
      collection_name: COLLECTION_NAME,
      data: generateInsertData(createCollectionParams.fields, 10),
    });

    await milvusClient.flush({
      collection_names: [COLLECTION_NAME],
    });
  });

  afterAll(async () => {
    await milvusClient.dropCollection({
      collection_name: COLLECTION_NAME,
    });
    await milvusClient.dropDatabase(dbParam);
  });

  it(`Compact should success and response should contain compactionPlanCount`, async () => {
    const res = await milvusClient.compact({
      collection_name: COLLECTION_NAME,
    });
    expect(res.status.error_code).toEqual(ErrorCode.SUCCESS);
    expect(res).toHaveProperty('compactionID');
    expect(res).toHaveProperty('compactionPlanCount');
  });

  it(`Compact with majorCompaction should success`, async () => {
    const res = await milvusClient.compact({
      collection_name: COLLECTION_NAME,
      majorCompaction: true,
    });
    expect(res.status.error_code).toEqual(ErrorCode.SUCCESS);
    expect(res).toHaveProperty('compactionID');
  });

  it(`Compact should forward target_size to server`, async () => {
    const res = await milvusClient.compact({
      collection_name: COLLECTION_NAME,
      target_size: 1,
    });
    expect(res.status.error_code).toEqual(ErrorCode.IllegalArgument);
    expect(res.status.reason).toContain('targetSize 1 MB');
  });

  it(`GetCompactionState should contain failedPlanNo`, async () => {
    const compactRes = await milvusClient.compact({
      collection_name: COLLECTION_NAME,
    });
    const res = await milvusClient.getCompactionState({
      compactionID: compactRes.compactionID,
    });
    expect(res.status.error_code).toEqual(ErrorCode.SUCCESS);
    expect(res).toHaveProperty('state');
    expect(res).toHaveProperty('executingPlanNo');
    expect(res).toHaveProperty('timeoutPlanNo');
    expect(res).toHaveProperty('completedPlanNo');
    expect(res).toHaveProperty('failedPlanNo');
  });

  it(`GetCompactionStateWithPlans should success`, async () => {
    const compactRes = await milvusClient.compact({
      collection_name: COLLECTION_NAME,
    });
    const res = await milvusClient.getCompactionStateWithPlans({
      compactionID: compactRes.compactionID,
    });
    expect(res.status.error_code).toEqual(ErrorCode.SUCCESS);
    expect(res).toHaveProperty('state');
    expect(res).toHaveProperty('mergeInfos');
  });

  it(`Compact should throw without collection_name`, async () => {
    try {
      await milvusClient.compact({
        collection_name: undefined as any,
      });
    } catch (error) {
      expect((error as Error).message).toEqual(
        ERROR_REASONS.COLLECTION_NAME_IS_REQUIRED
      );
    }
  });

  it(`GetCompactionState should throw without compactionID`, async () => {
    try {
      await milvusClient.getCompactionState({
        compactionID: undefined as any,
      });
    } catch (error) {
      expect((error as Error).message).toEqual(
        ERROR_REASONS.COMPACTION_ID_IS_REQUIRED
      );
    }
  });
});

import {
  AggregationBucket,
  DataType,
  ErrorCode,
  IndexType,
  MetricType,
  MilvusClient,
} from '../../milvus';
import { GENERATE_NAME, IP } from '../tools';

const milvusClient = new MilvusClient({ address: IP, logLevel: 'info' });
const COLLECTION_NAME = GENERATE_NAME('search_aggregation');

const rows = [
  {
    id: 1,
    vector: [1, 0],
    category: 'books',
    brand: 'acme',
    price: 10,
    rating: 4,
    in_stock: true,
  },
  {
    id: 2,
    vector: [0.99, 0.01],
    category: 'books',
    brand: 'acme',
    price: 20,
    rating: 5,
    in_stock: true,
  },
  {
    id: 3,
    vector: [0.98, 0.02],
    category: 'books',
    brand: 'zen',
    price: 30,
    rating: 3,
    in_stock: true,
  },
  {
    id: 4,
    vector: [0.97, 0.03],
    category: 'books',
    brand: 'zen',
    price: 40,
    rating: 4,
    in_stock: true,
  },
  {
    id: 5,
    vector: [0.96, 0.04],
    category: 'music',
    brand: 'acme',
    price: 50,
    rating: 2,
    in_stock: true,
  },
  {
    id: 6,
    vector: [0.95, 0.05],
    category: 'music',
    brand: 'acme',
    price: 60,
    rating: 3,
    in_stock: true,
  },
  {
    id: 7,
    vector: [0.94, 0.06],
    category: 'music',
    brand: 'zen',
    price: 70,
    rating: 4,
    in_stock: true,
  },
  {
    id: 8,
    vector: [0.93, 0.07],
    category: 'music',
    brand: 'zen',
    price: 80,
    rating: 5,
    in_stock: true,
  },
];

const keyValue = (bucket: any, fieldName: string) =>
  bucket.key.find((entry: any) => entry.field_name === fieldName)?.value;

describe('SearchAggregation API', () => {
  beforeAll(async () => {
    await milvusClient.createCollection({
      collection_name: COLLECTION_NAME,
      consistency_level: 'Strong',
      fields: [
        {
          name: 'id',
          data_type: DataType.Int64,
          is_primary_key: true,
        },
        {
          name: 'vector',
          data_type: DataType.FloatVector,
          dim: 2,
        },
        {
          name: 'category',
          data_type: DataType.VarChar,
          max_length: 32,
        },
        {
          name: 'brand',
          data_type: DataType.VarChar,
          max_length: 32,
        },
        {
          name: 'price',
          data_type: DataType.Int64,
        },
        {
          name: 'rating',
          data_type: DataType.Double,
        },
        {
          name: 'in_stock',
          data_type: DataType.Bool,
        },
      ],
    });

    const insert = await milvusClient.insert({
      collection_name: COLLECTION_NAME,
      data: rows,
    });
    expect(insert.status.error_code).toBe(ErrorCode.SUCCESS);

    await milvusClient.flush({ collection_names: [COLLECTION_NAME] });
    await milvusClient.createIndex({
      collection_name: COLLECTION_NAME,
      field_name: 'vector',
      index_type: IndexType.FLAT,
      metric_type: MetricType.L2,
    });
    await milvusClient.loadCollectionSync({
      collection_name: COLLECTION_NAME,
    });
  });

  afterAll(async () => {
    await milvusClient
      .releaseCollection({ collection_name: COLLECTION_NAME })
      .catch(() => undefined);
    await milvusClient
      .dropCollection({ collection_name: COLLECTION_NAME })
      .catch(() => undefined);
    await milvusClient.closeConnection();
  });

  it('returns bucket metrics, top hits, and nested aggregation per query', async () => {
    const result = await milvusClient.search({
      collection_name: COLLECTION_NAME,
      anns_field: 'vector',
      data: [
        [1, 0],
        [0.9, 0.1],
      ],
      limit: rows.length,
      filter: 'in_stock == true',
      output_fields: ['category', 'brand', 'price', 'rating', 'in_stock'],
      search_aggregation: {
        fields: ['category'],
        size: 2,
        metrics: {
          doc_count: { op: 'count', field_name: '*' },
          min_price: { op: 'min', field_name: 'price' },
          max_price: { op: 'max', field_name: 'price' },
          total_price: { op: 'sum', field_name: 'price' },
          avg_price: { op: 'avg', field_name: 'price' },
        },
        order: [{ key: 'total_price', direction: 'desc' }],
        top_hits: {
          size: 2,
          sort: [{ field_name: 'price', direction: 'asc' }],
        },
        sub_aggregation: {
          fields: ['brand'],
          size: 2,
          metrics: {
            doc_count: { op: 'count', field_name: '*' },
            avg_rating: { op: 'avg', field_name: 'rating' },
          },
          order: [{ key: 'avg_rating', direction: 'desc' }],
          top_hits: {
            size: 2,
            sort: [{ field_name: 'price', direction: 'asc' }],
          },
        },
      },
    });

    expect(result.status.error_code).toBe(ErrorCode.SUCCESS);
    expect(result.results).toEqual([]);
    const aggBuckets = (result.agg_buckets as unknown) as AggregationBucket[][];
    expect(aggBuckets).toHaveLength(2);

    aggBuckets.forEach(buckets => {
      expect(buckets).toHaveLength(2);
      expect(buckets.map(bucket => keyValue(bucket, 'category'))).toEqual([
        'music',
        'books',
      ]);

      const expectedByCategory = {
        books: { min: 10, max: 40, sum: 100, avg: 25 },
        music: { min: 50, max: 80, sum: 260, avg: 65 },
      };

      buckets.forEach(bucket => {
        const category = keyValue(bucket, 'category') as 'books' | 'music';
        const expected = expectedByCategory[category];
        expect(Number(bucket.count)).toBe(4);
        expect(Number(bucket.metrics.doc_count)).toBe(4);
        expect(Number(bucket.metrics.min_price)).toBe(expected.min);
        expect(Number(bucket.metrics.max_price)).toBe(expected.max);
        expect(Number(bucket.metrics.total_price)).toBe(expected.sum);
        expect(Number(bucket.metrics.avg_price)).toBeCloseTo(expected.avg);
        expect(bucket.hits).toHaveLength(2);
        expect(bucket.hits.map(hit => Number(hit.price))).toEqual(
          category === 'books' ? [10, 20] : [50, 60]
        );
        bucket.hits.forEach(hit => {
          expect(hit.category).toBe(category);
          expect(hit.in_stock).toBe(true);
        });

        expect(bucket.sub_groups).toHaveLength(2);
        const brands = bucket.sub_groups.map(subBucket =>
          keyValue(subBucket, 'brand')
        );
        expect(brands.sort()).toEqual(['acme', 'zen']);
        bucket.sub_groups.forEach(subBucket => {
          const brand = keyValue(subBucket, 'brand');
          expect(Number(subBucket.count)).toBe(2);
          expect(Number(subBucket.metrics.doc_count)).toBe(2);
          expect(subBucket.hits).toHaveLength(2);
          const prices = subBucket.hits.map(hit => Number(hit.price));
          expect(prices).toEqual([...prices].sort((a, b) => a - b));
          subBucket.hits.forEach(hit => {
            expect(hit.category).toBe(category);
            expect(hit.brand).toBe(brand);
          });
          const expectedAverage =
            subBucket.hits.reduce((sum, hit) => sum + Number(hit.rating), 0) /
            subBucket.hits.length;
          expect(Number(subBucket.metrics.avg_rating)).toBeCloseTo(
            expectedAverage
          );
        });
      });
    });
  });

  it('returns a flat bucket array for a single query vector', async () => {
    const result = await milvusClient.search({
      collection_name: COLLECTION_NAME,
      anns_field: 'vector',
      data: [1, 0],
      search_aggregation: {
        fields: ['category'],
        size: 2,
        metrics: {
          doc_count: { op: 'count', field_name: '*' },
        },
        order: [{ key: '_key', direction: 'asc' }],
      },
    });

    expect(result.status.error_code).toBe(ErrorCode.SUCCESS);
    expect(result.results).toEqual([]);
    expect(result.agg_buckets).toHaveLength(2);
    expect(
      result.agg_buckets!.map(bucket => keyValue(bucket, 'category'))
    ).toEqual(['books', 'music']);
  });
});

import path from 'path';
import protobuf from 'protobufjs';
import {
  DataType,
  HighlightType,
  SearchAggregation,
  buildSearchAggregation,
  buildSearchRequest,
  formatSearchAggregationResult,
} from '../../milvus';

const collectionInfo = {
  status: { error_code: 'Success', reason: '' },
  collection_name: 'products',
  collectionID: '1',
  consistency_level: 'Session',
  schema: {
    name: 'products',
    fields: [
      {
        name: 'id',
        fieldID: '1',
        dataType: DataType.Int64,
        data_type: 'Int64',
        is_primary_key: true,
      },
      {
        name: 'vector',
        fieldID: '2',
        dataType: DataType.FloatVector,
        data_type: 'FloatVector',
        type_params: [{ key: 'dim', value: '2' }],
        index_params: [],
      },
    ],
  },
  anns_fields: {
    vector: {
      dataType: DataType.FloatVector,
      data_type: 'FloatVector',
      type_params: [{ key: 'dim', value: '2' }],
      index_params: [],
    },
  },
} as any;

const milvusProto = protobuf.loadSync(
  path.resolve(__dirname, '../../proto/proto/milvus.proto')
);

const basicAggregation = (): SearchAggregation => ({
  fields: ['category'],
  size: 3,
  metrics: {
    doc_count: { op: 'count', field_name: '*' },
  },
});

describe('SearchAggregation', () => {
  it('builds metrics, top hits, ordering, and nested aggregation', () => {
    const aggregation = buildSearchAggregation({
      fields: ['category'],
      size: 3,
      metrics: {
        doc_count: { op: 'count', field_name: '*' },
        min_price: { op: 'min', field_name: 'price' },
        max_price: { op: 'max', field_name: 'price' },
        total_price: { op: 'sum', field_name: 'price' },
        avg_rating: { op: 'avg', field_name: 'rating' },
      },
      order: [
        { key: 'avg_rating', direction: 'desc' },
        { key: '_count', direction: 'desc' },
        { key: '_key', direction: 'asc' },
      ],
      top_hits: {
        size: 2,
        sort: [
          { field_name: 'price', direction: 'asc' },
          { field_name: '_score', direction: 'desc' },
        ],
      },
      sub_aggregation: {
        fields: ['brand'],
        size: 2,
        metrics: {
          brand_count: { op: 'count', field_name: '*' },
        },
      },
    });

    expect(aggregation).toEqual({
      fields: ['category'],
      size: 3,
      metrics: {
        doc_count: { op: 'count', field_name: '*' },
        min_price: { op: 'min', field_name: 'price' },
        max_price: { op: 'max', field_name: 'price' },
        total_price: { op: 'sum', field_name: 'price' },
        avg_rating: { op: 'avg', field_name: 'rating' },
      },
      order: [
        { key: 'avg_rating', direction: 'desc' },
        { key: '_count', direction: 'desc' },
        { key: '_key', direction: 'asc' },
      ],
      top_hits: {
        size: 2,
        sort: [
          { field_name: 'price', direction: 'asc' },
          { field_name: '_score', direction: 'desc' },
        ],
      },
      sub_aggregation: {
        fields: ['brand'],
        size: 2,
        metrics: {
          brand_count: { op: 'count', field_name: '*' },
        },
        order: [],
      },
    });
  });

  it.each([
    null,
    {},
    { fields: [], size: 1 },
    { fields: [''], size: 1 },
    { fields: ['meta["region"]'], size: 1 },
    { fields: ['brand'], size: 0 },
    { fields: ['brand'], size: 1, metrics: null },
    {
      fields: ['brand'],
      size: 1,
      metrics: { ' ': { op: 'count', field_name: '*' } },
    },
    {
      fields: ['brand'],
      size: 1,
      metrics: { bad: null },
    },
    {
      fields: ['brand'],
      size: 1,
      metrics: { bad: { op: 'count', field_name: ' ' } },
    },
    {
      fields: ['brand'],
      size: 1,
      metrics: { bad: { op: 'median', field_name: 'price' } },
    },
    {
      fields: ['brand'],
      size: 1,
      metrics: { bad: { op: 'avg', field_name: '*' } },
    },
    { fields: ['brand'], size: 1, order: null },
    { fields: ['brand'], size: 1, order: [{}] },
    {
      fields: ['brand'],
      size: 1,
      order: [{ key: 'unknown', direction: 'asc' }],
    },
    {
      fields: ['brand'],
      size: 1,
      order: [{ key: '_key', direction: 'sideways' }],
    },
    { fields: ['brand'], size: 1, top_hits: null },
    {
      fields: ['brand'],
      size: 1,
      top_hits: { size: 0 },
    },
    {
      fields: ['brand'],
      size: 1,
      top_hits: { size: 1, sort: null },
    },
    {
      fields: ['brand'],
      size: 1,
      top_hits: { size: 1, sort: [{}] },
    },
    {
      fields: ['brand'],
      size: 1,
      top_hits: {
        size: 1,
        sort: [{ field_name: '_score', direction: 'sideways' }],
      },
    },
  ])('rejects invalid configurations', aggregation => {
    expect(() => buildSearchAggregation(aggregation as any)).toThrow();
  });

  it('rejects aggregation nesting deeper than four levels', () => {
    let aggregation: any = { fields: ['level_5'], size: 1 };
    for (let level = 4; level >= 1; level--) {
      aggregation = {
        fields: [`level_${level}`],
        size: 1,
        sub_aggregation: aggregation,
      };
    }

    expect(() => buildSearchAggregation(aggregation)).toThrow(
      'at most 4 levels'
    );
  });

  it('adds a plain aggregation object to a regular search request', () => {
    const searchAggregation = basicAggregation();
    const result = buildSearchRequest(
      {
        collection_name: 'products',
        data: [0.1, 0.2],
        search_aggregation: searchAggregation,
      },
      collectionInfo,
      milvusProto
    );

    expect(result.isHybridSearch).toBe(false);
    expect((result.request as any).search_aggregation).toEqual({
      ...searchAggregation,
      order: [],
    });
  });

  it.each([
    { group_by_field: 'brand', error: 'group_by_field' },
    { params: { group_by_field: 'brand' }, error: 'group_by_field' },
    { group_by_fields: ['brand'], error: 'group_by_fields' },
    { params: { group_by_fields: ['brand'] }, error: 'group_by_fields' },
    { offset: 1, error: 'offset' },
    { params: { offset: 1 }, error: 'offset' },
    {
      highlighter: { type: HighlightType.Lexical },
      error: 'highlighter',
    },
  ])('rejects incompatible search options: $error', option => {
    expect(() =>
      buildSearchRequest(
        {
          collection_name: 'products',
          data: [0.1, 0.2],
          search_aggregation: basicAggregation(),
          ...option,
        } as any,
        collectionInfo,
        milvusProto
      )
    ).toThrow(option.error);
  });

  it('rejects search aggregation in hybrid search', () => {
    expect(() =>
      buildSearchRequest(
        {
          collection_name: 'products',
          data: [{ anns_field: 'vector', data: [0.1, 0.2] }],
          search_aggregation: basicAggregation(),
        } as any,
        collectionInfo,
        milvusProto
      )
    ).toThrow('hybrid search');
  });

  it('parses typed metrics, top hits, and nested buckets', () => {
    const result = formatSearchAggregationResult({
      results: {
        num_queries: 1,
        agg_topks: ['1'],
        agg_buckets: [
          {
            key: [
              {
                field_id: '10',
                field_name: 'category',
                string_val: 'books',
                value: 'string_val',
              },
              {
                field_id: '11',
                field_name: 'featured',
                bool_val: false,
                value: 'bool_val',
              },
            ],
            count: '9007199254740993',
            metrics: {
              total: {
                int_val: '9007199254740995',
                value: 'int_val',
              },
              average: { double_val: 12.5, value: 'double_val' },
              label: { string_val: 'popular', value: 'string_val' },
              active: { bool_val: true, value: 'bool_val' },
            },
            hits: [
              {
                int_pk: '9007199254740997',
                pk: 'int_pk',
                score: 0.25,
                fields: [
                  {
                    field_id: '20',
                    field_name: 'price',
                    int_val: '99',
                    value: 'int_val',
                  },
                  {
                    field_id: '21',
                    field_name: 'rating',
                    double_val: 4.5,
                    value: 'double_val',
                  },
                ],
              },
            ],
            sub_groups: [
              {
                key: [
                  {
                    field_id: '30',
                    field_name: 'brand',
                    string_val: 'acme',
                    value: 'string_val',
                  },
                ],
                count: '1',
                metrics: {},
                hits: [],
                sub_groups: [],
              },
            ],
          },
        ],
      },
    } as any);

    const bucket = result[0][0];
    expect(bucket.key.map(entry => entry.value)).toEqual(['books', false]);
    expect(bucket.count).toBe('9007199254740993');
    expect(bucket.metrics).toEqual({
      total: '9007199254740995',
      average: 12.5,
      label: 'popular',
      active: true,
    });
    expect(bucket.hits[0]).toEqual({
      id: '9007199254740997',
      score: 0.25,
      price: '99',
      rating: 4.5,
    });
    expect(bucket.sub_groups[0].key[0].value).toBe('acme');
  });

  it('splits top-level buckets by agg_topks', () => {
    const bucket = (count: number) => ({
      key: [],
      count,
      metrics: {},
      hits: [],
      sub_groups: [],
    });
    const result = formatSearchAggregationResult({
      results: {
        num_queries: 3,
        agg_topks: ['2', '1', '3'],
        agg_buckets: [1, 2, 3, 4, 5, 6].map(bucket),
      },
    } as any);

    expect(result.map(buckets => buckets.map(item => item.count))).toEqual([
      [1, 2],
      [3],
      [4, 5, 6],
    ]);
  });

  it('handles protobuf oneofs without discriminators', () => {
    const result = formatSearchAggregationResult({
      results: {
        primary_field_name: 'product_id',
        num_queries: 1,
        agg_topks: [],
        agg_buckets: [
          {
            key: [
              { field_id: '10', field_name: '', int_val: '7' },
              { field_id: '11', field_name: 'missing' },
            ],
            count: '1',
            metrics: {
              count: { int_val: '1' },
              missing: {},
            },
            hits: [
              {
                str_pk: 'product-1',
                score: 0.5,
                fields: [
                  {
                    field_id: '20',
                    field_name: '',
                    string_val: 'value',
                  },
                  { field_id: '21', field_name: 'missing' },
                ],
              },
            ],
            sub_groups: [],
          },
        ],
      },
    } as any);

    expect(result[0][0]).toEqual({
      key: [
        { field_id: '10', field_name: '10', value: '7' },
        { field_id: '11', field_name: 'missing', value: undefined },
      ],
      count: '1',
      metrics: { count: '1', missing: undefined },
      hits: [{ product_id: 'product-1', score: 0.5, '20': 'value' }],
      sub_groups: [],
    });
  });

  it('returns empty buckets and appends unmatched trailing buckets', () => {
    expect(
      formatSearchAggregationResult({
        results: { num_queries: 1, agg_topks: [], agg_buckets: [] },
      } as any)
    ).toEqual([]);

    const result = formatSearchAggregationResult({
      results: {
        num_queries: 2,
        agg_topks: ['1', '0'],
        agg_buckets: [
          { key: [], count: 1, metrics: {}, hits: [], sub_groups: [] },
          { key: [], count: 2, metrics: {}, hits: [], sub_groups: [] },
        ],
      },
    } as any);

    expect(result.map(buckets => buckets.map(bucket => bucket.count))).toEqual([
      [1],
      [2],
    ]);
  });

  it('does not guess bucket ownership without agg_topks for multiple queries', () => {
    const result = formatSearchAggregationResult({
      results: {
        num_queries: 2,
        agg_topks: [],
        agg_buckets: [
          { key: [], count: 1, metrics: {}, hits: [], sub_groups: [] },
        ],
      },
    } as any);

    expect(result).toEqual([[], []]);
  });
});

